    public function up(): void
    {
        $users = DB::table('users')->whereIn('display_name', self::CRAS)->pluck('id', 'display_name')->all();
        // A database without the CRAs (a fresh or test one) gets nothing.
        if ($users === []) {
            return;
        }
        $users['Sharie'] ??= $this->sharie();

        foreach ($this->months as $month => $cards) {
            if (DB::table('actual_income_statements')->whereDate('month', $month.'-01')->exists()) {
                continue;
            }

            foreach ($cards as $card => $figures) {
                if ($card !== 'CRD' && ! isset($users[$card])) {
                    continue;
                }

                DB::table('actual_income_statements')->insert([
                    'month' => $month.'-01', 'user_id' => $card === 'CRD' ? null : $users[$card], 'figures' => json_encode($figures),
                    'created_at' => now(), 'updated_at' => now(),
                ]);
            }
        }
    }

    /**
     * Sharie Galano as an inactive CRA (she can't sign in), or the user already named Sharie.
     */
    private function sharie(): ?int
    {
        $existing = DB::table('users')->where('name', 'like', '%Sharie%')->orWhere('display_name', 'like', '%Sharie%')->value('id');
        $role = DB::table('roles')->where('slug', 'cra')->value('id');
        if ($existing !== null || $role === null) {
            return $existing;
        }

        return DB::table('users')->insertGetId([
            'name' => 'Sharie Galano', 'display_name' => 'Sharie', 'email' => 'sharie.galano@crd-deck.invalid',
            'role_id' => $role, 'is_active' => false, 'created_at' => now(), 'updated_at' => now(),
        ]);
    }

    /**
     * Reverse the migrations.
     */
    public function down(): void
    {
        foreach (array_keys($this->months) as $month) {
            DB::table('actual_income_statements')->whereDate('month', $month.'-01')->delete();
        }
    }
